"""Build the English submission overview. Pass --repository-url after publication."""
import argparse
from pathlib import Path
from xml.sax.saxutils import escape

from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--repository-url")
    parser.add_argument("--evaluated", action="store_true")
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[1]
    output = root / "output/pdf/Fernando dAvila Filho - AI Engineer - Full-Stack Generative AI Applications.pdf"
    output.parent.mkdir(parents=True, exist_ok=True)
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(name="TitleCustom", fontName="Helvetica-Bold", fontSize=24, leading=29, textColor=colors.HexColor("#103B43"), spaceAfter=18))
    styles.add(ParagraphStyle(name="SectionCustom", fontName="Helvetica-Bold", fontSize=13, leading=17, textColor=colors.HexColor("#103B43"), spaceBefore=16, spaceAfter=8))
    styles.add(ParagraphStyle(name="BodyCustom", fontName="Helvetica", fontSize=10.5, leading=15, spaceAfter=9, alignment=TA_LEFT))
    story = []
    def p(text, style="BodyCustom"):
        story.append(Paragraph(text, styles[style]))
    def heading(text):
        p(text, "SectionCustom")
    p("ARTEFACT / TECHNICAL CASE", "SectionCustom")
    p("Empório da Música<br/>Customer Support Agent", "TitleCustom")
    p("<b>Fernando d'Ávila Filho</b><br/>AI Engineer - Full-Stack Generative AI Applications<br/>Submission overview | November 2026")
    heading("Project access")
    if args.repository_url:
        url = escape(args.repository_url)
        p(f'Public repository: <link href="{url}" color="#087D8A">{url}</link>')
    else:
        p("<b>Review draft:</b> the implementation is prepared locally. Public repository publication and its URL are pending. This document is not yet ready for submission.")
    heading("Problem and approach")
    p("The store team receives recurring questions about instruments, prices, availability, orders and store rules. Mel is a Python text assistant that retrieves the appropriate evidence before answering, using a friendly and professional persona aligned with the store manual.")
    p("The prototype combines local LLM tool calling with deterministic business tools. Product and order questions use structured CSV lookups; policy questions retrieve relevant pages from the original PDF. The interface is a command-line conversation, keeping the focus on correct support behavior.")
    heading("Architecture")
    rows = [["Layer", "Implementation"], ["Interaction", "CLI with session memory and /reset"], ["Reasoning", "Ollama + Qwen3 8B, local inference"], ["Structured lookup", "Read-only product, promotion and order tools"], ["Policy retrieval", "Lexical page ranking with bilingual keyword hints"], ["Controls", "Allowlisted tools, argument validation, bounded loop"]]
    table = Table([[Paragraph(escape(c), styles["BodyCustom"]) for c in row] for row in rows], colWidths=[115, 365])
    table.setStyle(TableStyle([("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#E7F1F2")), ("VALIGN", (0, 0), (-1, -1), "TOP"), ("LINEBELOW", (0, 0), (-1, -1), .4, colors.HexColor("#D6E0E2")), ("TOPPADDING", (0, 0), (-1, -1), 8), ("BOTTOMPADDING", (0, 0), (-1, -1), 3)]))
    story.append(table)
    story.append(PageBreak())
    heading("Technical decisions")
    p("<b>Simple Python orchestration.</b> Three explicit tools make the boundary between generation and factual data easy to inspect. No unrestricted SQL, shell access or write operations are exposed to the model. A five-round budget prevents endless tool loops.")
    p("<b>Local inference.</b> Ollama and Qwen3 8B avoid a paid API and keep inference on the host machine. Hardware capacity and model quality remain practical constraints. The model is configurable; the README describes setup and reproducibility limits.")
    p("<b>Small-data retrieval.</b> The supplied manual has eight pages and the catalog has 65 products. Lexical PDF retrieval and typed filters are proportionate to this size. Retrieval returns source page numbers; prices and discounts are calculated with Decimal rather than generated by the model.")
    p("<b>Session memory.</b> The last four complete turns are retained in memory only. No conversation is persisted to disk by the CLI. A reset clears the conversation.")
    heading("Important business and privacy boundaries")
    p("CSV files are reread on every product lookup, allowing updates to appear in the next response. They remain a supplied snapshot, not a live ERP or carrier integration. Only active products with positive stock are available by default. Only promotions explicitly marked active apply, and PIX discounts never stack with promotional prices.")
    p("Order access requires an identity supplied by trusted application code and an ownership check. The CLI has no authentication mechanism, so order requests are redirected to an authenticated store channel. The model cannot establish identity from an order number, email or customer claim.")
    p("The manual contains conflicting contact and installment information, an undefined shipping boundary at exactly BRL 500, and overlapping exchange and warranty guidance. Mel is instructed to acknowledge uncertainty and request human confirmation. It must not approve refunds or decide statutory rights.")
    p("Order records do not contain the actual receipt date or purchase channel. Online return discussions therefore ask for these facts rather than inferring them from estimated delivery. Complaints, returns and reservations are advisory only; the agent cannot claim they were processed.")
    heading("Validation and examples")
    p("The automated suite passes 19 tests covering catalog filters, pricing, inactive promotions, fresh CSV reads, policy retrieval, order ownership, invalid tool calls, provider errors and loop/memory limits. Scripted responses validate the orchestration protocol and do not establish real-model quality.")
    p("Five real-model conversations are included in examples/ and cover catalog search, general information, returns, promotion stacking, privacy and scope." if args.evaluated else "A five-scenario real-model evaluation script is provided. Real-model execution is still pending; no fabricated transcripts are presented as model output.")
    story.append(PageBreak())
    heading("Running the project")
    p("Install Python 3.11+ and Ollama. From the repository root, create a virtual environment, install the package, pull the model and start the CLI. The full README contains troubleshooting and configuration details.")
    for command in ["python3 -m venv .venv", "source .venv/bin/activate", "python -m pip install -e .", "ollama pull qwen3:8b", "ollama serve", "python -m emporio.cli", "python -m unittest discover -s tests -v", "python scripts/evaluate.py"]:
        p(f'<font face="Courier" size="9">{escape(command)}</font>')
    p("Run the CLI in a second terminal while Ollama serves. Skip the serve command if Ollama is already active. The initial model download is approximately 5.2 GB; no paid API key is required.")
    heading("Limitations and next steps")
    p("This is a local CLI prototype. There is no deployed WhatsApp channel, production authentication, real-time inventory, carrier integration or operational handoff. Lexical retrieval can miss paraphrases. Model adherence to grounding and scope instructions is not guaranteed, and read-only tools do not eliminate prompt injection.")
    p("Next steps would prioritize a labeled evaluation set and adversarial testing, data validation, pinned runtime/model versions, transactional source APIs, verified customer identity and an auditable handoff queue. A web interface and richer retrieval should follow measured needs rather than precede validation.")
    heading("AI assistance disclosure")
    p("OpenAI Codex assisted with file inspection, implementation, policy ambiguity analysis, regression tests and English documentation. Generated work was checked against supplied data and automated tests. Scripted protocol tests are distinguished from real-model evaluation. The candidate should review and understand all code and assumptions before submission.")
    heading("Source materials")
    p("Artefact technical challenge, supplied operational CSVs, and Empório da Música policy manual v2.1 (June 2025). Original data remain in Portuguese. Technical references: docs.ollama.com/api/chat and docs.ollama.com/capabilities/tool-calling.")
    def footer(canvas, doc):
        canvas.setStrokeColor(colors.HexColor("#D6E0E2"))
        canvas.line(48, 42, A4[0] - 48, 42)
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.HexColor("#56686D"))
        canvas.drawString(48, 28, "Fernando d'Avila Filho | Artefact AI Engineer")
        canvas.drawRightString(A4[0] - 48, 28, str(doc.page))
    SimpleDocTemplate(str(output), pagesize=A4, leftMargin=48, rightMargin=48, topMargin=40, bottomMargin=56).build(story, onFirstPage=footer, onLaterPages=footer)
    print(output)


if __name__ == "__main__":
    main()
